return ['domain'=>NULL,'plural-forms'=>'nplurals=4; plural=(n%100==1 ? 0 : n%100==2 ? 1 : n%100==3 || n%100==4 ? 2 : 3);','language'=>'sl_SI','project-id-version'=>'TranslatePress Multilingual','pot-creation-date'=>'2026-10-13T10:48:01+03:00','po-revision-date'=>'2026-10-13T10:48:01+03:00','x-generator'=>'TranslatePress build (community + OpenRouter), 2026-10-13','messages'=>['TranslatePress - DEV'=>'TranslatePress - DEV','https://translatepress.com/'=>'https://translatepress.com/','Experience a better way of translating your WordPress site using a visual front-end translation editor, with full support for WooCommerce and site builders.'=>'Odkrijte boljši način prevajanja vaše spletne strani WordPress z vizualnim urejevalnikom prevodov v čelni strani, ki v celoti podpira WooCommerce in graditelje strani.','Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban'=>'Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban','https://cozmoslabs.com/'=>'https://cozmoslabs.com/','Active'=>'Aktivno','The inactive languages will still be visible and active for the admin. For other users they won\'t be visible in the language switchers and won\'t be accessible either.'=>'Neaktivni jeziki bodo še vedno vidni in aktivni za administratorja. Za druge uporabnike ne bodo vidni v izbirnikih jezikov in tudi dostopni ne bodo.','unknown'=>'neznano','<strong>Extra Languages add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>Dodatek Extra Languages</strong> zahteva različico TranslatePress %1$s ali višje. Trenutno uporabljate različico %2$s. Posodobite TranslatePress, da omogočite to funkcijo.','Dismiss this notice.'=>'Zapri to obvestilo.','Post Slug'=>'Slug objave','URL Slugs Translation'=>'Prevajanje URL slugov','Slugs'=>'Slugi','Taxonomy Slugs'=>'Slugi taksonomij','Search Taxonomy Slugs'=>'Išči taksonomske sluge','Taxonomy Slug'=>'Slug taksonomije','Translation'=>'Prevod','Term Slugs'=>'Slugi pojmov','Search Term Slugs'=>'Išči sluge pojmov','Term Slug'=>'Slug pojma','Taxonomy'=>'Taksonomija','Filter by Taxonomy'=>'Filtriraj po taksonomiji','Post Slugs'=>'Slugi objav','Search Post Slugs'=>'Išči sluge objav','Post ID'=>'ID objave','Post Type'=>'Vrsta objave','Filter by Post Type'=>'Filtriraj po vrsti objave','Published'=>'Objavljeno','Any Post Status'=>'Kateri koli status objave','Post Type Base Slugs'=>'Slugs baz vrst objav','Post Type Base Slug'=>'Slug baze vrste objave','Search Post Type Base Slugs'=>'Iskanje slugs baz vrst objav','WooCommerce Slugs'=>'WooCommerce slugs','WooCommerce Slug'=>'WooCommerce slug','Search WooCommerce Slugs'=>'Iskanje WooCommerce slugs','Automatic and manual slug translation changes performed when <strong>TranslatePress - Multilingual</strong> 2.8.4 was active had to be removed because of some issues with that version. All slug translations from before that version are now in use. Thank you for understanding!'=>'Samodejne in ročne spremembe prevodov slugov, opravljene, ko je bil aktiven <strong>TranslatePress - Multilingual</strong> 2.8.4, so morale biti odstranjene zaradi nekaterih težav s to različico. Vsi prevodi slugov iz obdobja pred to različico so zdaj v uporabi. Hvala za razumevanje!','If you absolutely need them, the removed translations can be found in tables trp_slug_original_obsolete and trp_slug_translation_obsolete.'=>'Če jih nujno potrebujete, so odstranjeni prevodi na voljo v tabelah trp_slug_original_obsolete in trp_slug_translation_obsolete.','(inactive)'=>'(neaktiven)','Other Slugs'=>'Drugi slugs','Search Other Slugs'=>'Iskanje drugih slugs','Automatic User Language Detection'=>'Samodejno zaznavanje jezika uporabnika','Invalid language code'=>'Neveljavna koda jezika','We\'ve detected you might be speaking a different language. Do you want to change to:'=>'Zaznali smo, da morda govorite drug jezik. Ali želite preklopiti na:','Change Language'=>'Spremeni jezik','Close and do not switch language'=>'Zapri in ne preklopi jezika','First by browser language, then IP address (recommended)'=>'Najprej po jeziku brskalnika, nato po IP naslovu (priporočeno)','First by IP address, then by browser language'=>'Najprej po IP naslovu, nato po jeziku brskalnika','Only by browser language'=>'Samo po jeziku brskalnika','Only by IP address'=>'Samo po naslovu IP','A popup appears asking the user if they want to be redirected'=>'Pojavi se pojavno okno, ki uporabnika vpraša, ali želi biti preusmerjen','Redirect directly (*not recommended)'=>'Neposredna preusmeritev (*ni priporočljivo)','Pop-up window over the content'=>'Pojavno okno nad vsebino','Hello bar before the content'=>'Obvestilna vrstica pred vsebino','Automatic User Language Detection requires a newer version of TranslatePress to use its visual settings interface. The legacy settings form will remain available until TranslatePress is updated.'=>'Za uporabo vizualnega vmesnika nastavitev samodejne zaznave jezika uporabnika je potrebna novejša različica TranslatePress. Stari obrazec za nastavitve bo ostal na voljo do posodobitve TranslatePressa.','Update TranslatePress'=>'Posodobi TranslatePress','WARNING. Cannot determine your language preference based on your current IP.<br>This is most likely because the website is on a local environment.'=>'OPOZORILO. Na podlagi vašega trenutnega naslova IP ni mogoče določiti vaše jezikovne preference.<br>To je najverjetneje zato, ker je spletišče v lokalnem okolju.','Permission denied.'=>'Dovoljenje zavrnjeno.','Invalid nonce.'=>'Neveljaven nonce.','Invalid settings.'=>'Neveljavne nastavitve.','Settings saved.'=>'Nastavitve so shranjene.','Go to <a href="%s" target="_self">Advanced</a> tab to change this feature\'s settings'=>'Pojdite na zavihek <a href="%s" target="_self">Napredno</a>, da spremenite nastavitve te funkcije','Website language selector'=>'Izbirnik jezika spletnega mesta','Change language'=>'Spremeni jezik','Available languages'=>'Razpoložljivi jeziki','Please enter your DeepL API key.'=>'Vnesite svoj DeepL API ključ.','DeepL'=>'DeepL','Bad request. There was an error accessing the DeepL API.'=>'Napačna zahteva. Pri dostopu do DeepL API je prišlo do napake.','The API key entered is invalid.'=>'Vneseni API ključ je neveljaven.','The API resource could not be found.'=>'Vira API ni bilo mogoče najti.','The request size is too large.'=>'Velikost zahteve je prevelika.','The request is too long.'=>'Zahteva je predolga.','Too many requests. Please try again later.'=>'Preveč zahtev. Poskusite znova pozneje.','Your translation quota has been reached.'=>'Vaša kvota za prevode je bila dosežena.','We could not process your request. Please try again later.'=>'Vaše zahteve nismo mogli obdelati. Poskusite znova pozneje.','There is an error on the DeepL service and your request could not be processed.'=>'V storitvi DeepL je prišlo do napake in vaše zahteve ni bilo mogoče obdelati.','DeepL API Type'=>'Vrsta DeepL API','Pro'=>'Pro','Free'=>'Brezplačno','Select the type of DeepL API you want to use.'=>'Izberite vrsto DeepL API, ki jo želite uporabljati.','DeepL API Key'=>'Ključ DeepL API','Visit <a href="%s" target="_blank">this link</a> to see how you can set up an API key and control API costs.'=>'Obiščite <a href="%s" target="_blank">to povezavo</a>, da vidite, kako lahko nastavite API ključ in nadzorujete stroške API.','No Active License Detected for this website.'=>'Za to spletno mesto ni zaznane aktivne licence.','Enter your license key'=>'Vnesite licenčni ključ',' Or %1$spurchase one here%2$s'=>' Ali %1$skuplite ga tukaj%2$s','Different Domain per Language'=>'Različna domena za vsak jezik','View Docs'=>'Ogled dokumentacije','Assign different domains or subdomains to each language. When visitors access these domains, TranslatePress loads the appropriate language translation directly without redirecting.'=>'Dodeli različne domene ali poddomene vsakemu jeziku. Ko obiskovalci dostopijo do teh domen, TranslatePress neposredno naloži ustrezen jezikovni prevod brez preusmeritve.','Example: %1$s for English, %2$s for Spanish, %3$s for French.'=>'Primer: %1$s za angleščino, %2$s za španščino, %3$s za francoščino.','Before enabling:'=>'Pred omogočitvijo:','Ensure your domains are registered, pointed to your server, and have SSL certificates configured.'=>'Poskrbite, da so vaše domene registrirane, usmerjene na vaš strežnik in da imajo konfigurirana SSL potrdila.','Domain'=>'Domena','Map this language to a different domain or sub-domain.'=>'Preslikajte ta jezik na drugo domeno ali poddomeno.','https://example.com'=>'https://example.com','Prefill with current domain'=>'Predizpolni s trenutno domeno','Check DNS'=>'Preveri DNS','Checking DNS...'=>'Preverjanje DNS...','DNS is correctly configured!'=>'DNS je pravilno konfiguriran!','DNS check failed. Please verify your domain configuration.'=>'Preverjanje DNS ni uspelo. Preverite konfiguracijo domene.','This domain is already assigned to another language.'=>'Ta domena je že dodeljena drugemu jeziku.','<strong>Different Domain per Language add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>Razširitev za različno domeno na jezik</strong> zahteva TranslatePress različice %1$s ali višjo. Trenutno uporabljate različico %2$s. Posodobite TranslatePress, da omogočite to funkcijo.','Note: This option is disabled when Different Domain for Language addon is active.'=>'Opomba: Ta možnost je onemogočena, ko je aktivna razširitev za različno domeno na jezik.','Different Domain per Language: Domain is required when domain mapping is enabled. The toggle has been disabled for languages with empty domains.'=>'Različna domena na jezik: Domena je obvezna, ko je preslikava domen omogočena. Stikalo je bilo onemogočeno za jezike s praznimi domenami.','Different Domain per Language: The same domain cannot be assigned to multiple languages. The toggle has been disabled for duplicate domains.'=>'Različna domena na jezik: Ista domena ne more biti dodeljena več jezikom. Stikalo je bilo onemogočeno za podvojene domene.','Different Domain per Language: A language domain cannot be the same as the main site URL. The toggle has been disabled for the matching domain.'=>'Različna domena na jezik: Domena jezika ne more biti enaka glavnemu URL-ju spletišča. Stikalo je bilo onemogočeno za ujemajočo se domeno.','Please enter a domain.'=>'Vnesite domeno.','Invalid domain format.'=>'Neveljavna oblika domene.','Could not reach domain: %s'=>'Domene ni bilo mogoče doseči: %s','Domain is reachable!'=>'Domena je dosegljiva!','Domain returned HTTP status %d.'=>'Domena je vrnila HTTP status %d.','Limit this menu item to the following languages'=>'Omeji ta element menija na naslednje jezike','All Languages'=>'Vsi jeziki','Translator'=>'Prevajalec',' TranslatePress Settings'=>' Nastavitve TranslatePress','Allow this user to translate the website.'=>'Dovoli temu uporabniku prevajanje spletnega mesta.','Translate Site'=>'Prevedi spletno mesto','Add-On'=>'Dodatek','Deactivate'=>'Deaktiviraj','Activate'=>'Aktiviraj','Installing...'=>'Nameščanje...','This add-on can not be activated back without a valid license. Are you sure you want to deactivate it?'=>'Tega dodatka ni mogoče ponovno aktivirati brez veljavne licence. Ali ste prepričani, da ga želite deaktivirati?','Documentation'=>'Dokumentacija','A valid license is required to activate add-ons.'=>'Za aktivacijo dodatkov je potrebna veljavna licenca.','Activate all'=>'Aktiviraj vse','Add-ons can not be activated back without a valid license. Are you sure you want to deactivate them?'=>'Dodatkov ni mogoče ponovno aktivirati brez veljavne licence. Ali ste prepričani, da jih želite deaktivirati?','Deactivate all'=>'Deaktiviraj vse','%1$sAdd-ons settings saved successfully%2$s'=>'%1$sNastavitve dodatkov so bile uspešno shranjene.%2$s','Date format'=>'Format datuma','Customize the date formatting per each translated language.<br/>Leave empty for default WP setting or see more information <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatting Date and Time" target="_blank">here</a>'=>'Prilagodi oblikovanje datuma za vsak prevedeni jezik.<br/>Pustite prazno za privzeto nastavitev WP ali si oglejte več informacij <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatting Date and Time" target="_blank">tukaj</a>','To edit an existing TranslatePress language, input the language code and fill in only the columns you want to overwrite (e.g. Language name, Flag).<br>You can also add new custom languages. They will be available under General settings, All Languages list, where the URL slug can be edited.'=>'Za urejanje obstoječega jezika TranslatePress vnesite kodo jezika in izpolnite le stolpce, ki jih želite prepisati (npr. ime jezika, zastava).<br>Lahko dodate tudi nove jezike po meri. Ti bodo na voljo pod splošnimi nastavitvami, na seznamu vseh jezikov, kjer je mogoče urediti URL slug.','For custom flag, first upload the image in media library then paste the URL.<br>Changing or deleting a custom language will impact translations and site URL\'s.<br>The Language code and the ISO Code should contain only alphabetical values, numerical values, "-" and "_".<br>The ISO Codes can be found on <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Google ISO Codes</a> and <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">DeepL Target Codes</a>.'=>'Za zastavo po meri najprej naložite sliko v medijsko knjižnico, nato prilepite URL.<br>Sprememba ali brisanje jezika po meri bo vplivala na prevode in URL-je spletnega mesta.<br>Koda jezika in ISO koda morata vsebovati samo abecedne vrednosti, številčne vrednosti, "-" in "_".<br>ISO kode najdete na <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Google ISO kode</a> in <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">DeepL ciljne kode</a>.','Language code'=>'Koda jezika','Language name'=>'Ime jezika','Native name'=>'Izvorno ime','ISO Code'=>'ISO koda','Flag URL'=>'URL zastave','Text RTL'=>'RTL besedilo','Custom language'=>'Jezik po meri','Disable bundled plugin translations'=>'Onemogoči priložene prevode vtičnika','By default, TranslatePress ships its own translation files in <code>wp-content/plugins/translatepress/languages/</code> and forces WordPress to use them instead of the language packs installed automatically from translate.wordpress.org.<br/>Enable this option to disable that override. WordPress will then load the community language pack from <code>wp-content/languages/plugins/</code> (if present) and fall back to the bundled files only when no pack is available.'=>'TranslatePress privzeto vsebuje lastne prevodne datoteke v <code>wp-content/plugins/translatepress/languages/</code> in prisili WordPress, da jih uporabi namesto jezikovnih paketov, ki so samodejno nameščeni s translate.wordpress.org.<br/>Omogočite to možnost, da onemogočite to preglasitev. WordPress bo nato naložil jezikovni paket skupnosti iz <code>wp-content/languages/plugins/</code> (če obstaja) in se vrnil na priložene datoteke le, ko paket ni na voljo.','Disable dynamic translation'=>'Onemogoči dinamični prevod','It disables detection of strings displayed dynamically using JavaScript. <br/>Strings loaded via a server side AJAX call will still be translated.'=>'Onemogoči zaznavanje nizov, ki so prikazani dinamično z uporabo JavaScripta. <br/>Nizi, naloženi prek strežniškega klica AJAX, bodo še vedno prevedeni.','Disable translation for gettext strings'=>'Onemogoči prevajanje nizov Gettext','Gettext Strings are strings outputted by themes and plugins. <br> Translating these types of strings through TranslatePress can be unnecessary if they are already translated using the .po/.mo translation file system.<br>Enabling this option can improve the page load performance of your site in certain cases. The disadvantage is that you can no longer edit gettext translations using TranslatePress, nor benefit from automatic translation on these strings.'=>'Gettext nizi so nizi, ki jih izpišejo teme in vtičniki. <br> Prevajanje teh vrst nizov prek TranslatePress je lahko nepotrebno, če so že prevedeni z uporabo sistema prevajalskih datotek .po/.mo.<br>Omogočitev te možnosti lahko v določenih primerih izboljša hitrost nalaganja strani vašega spletnega mesta. Slabost je, da teh prevodov gettext ni več mogoče urejati v TranslatePress, niti ni mogoče samodejno prevajati teh nizov.','Gettext Strings translation is disabled'=>'Prevajanje Gettext nizov je onemogočeno','To enable it go to '=>'Za omogočitev pojdite na ','TranslatePress->Advanced Settings->Debug->Disable translation for gettext strings'=>'TranslatePress->Napredne nastavitve->Razhroščevanje->Onemogoči prevajanje nizov Gettext',' and uncheck the Checkbox.'=>' in počistite potrditveno polje.','Dismiss'=>'Opusti','Exclude translated links from sitemap'=>'Izključi prevedene povezave iz sitemap','Do not include translated links in sitemaps generated by SEO plugins.<br/>Requires <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> SEO Pack Add-on</a> to be installed and activated.'=>'Ne vključujte prevedenih povezav v sitemaps, ki jih ustvarjajo SEO vtičniki.<br/>Zahteva nameščen in aktiviran <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> dodatek SEO Pack</a>.','Disable post container tags for post title'=>'Onemogoči oznake vsebnika za naslov prispevka','It disables search indexing the post title in translated languages.<br/>Useful when the title of the post doesn\'t allow HTML thus breaking the page.'=>'Onemogoči indeksiranje naslova prispevka v prevedenih jezikih.<br/>Uporabno, kadar naslov prispevka ne dovoli HTML-ja in se stran zaradi tega pokvari.','Disable post container tags for post content'=>'Onemogoči oznake vsebnika za vsebino prispevka','It disables search indexing the post content in translated languages.<br/>Useful when the content of the post doesn\'t allow HTML thus breaking the page.'=>'Onemogoči indeksiranje vsebine prispevka v prevedenih jezikih.<br/>Uporabno, kadar vsebina prispevka ne dovoli HTML-ja in se stran zaradi tega pokvari.','Do not translate certain paths'=>'Ne prevajaj določenih poti','Choose what paths can be translated. Supports wildcard at the end of the path.<br>For example, to exclude https://example.com/some/path you can either use the rule /some/path/ or /some/*.<br>Enter each rule on it\'s own line. To exclude the home page use {{home}}.'=>'Izberite, katere poti so lahko prevedene. Podpira nadomestni znak na koncu poti.<br>Na primer, da izključite https://example.com/some/path, lahko uporabite pravilo /some/path/ ali /some/*.<br>Vnesite vsako pravilo v svojo vrstico. Da izključite domačo stran, uporabite {home}.','Exclude Paths From Translation'=>'Izključi poti iz prevoda','Translate Only Certain Paths'=>'Prevedi samo določene poti','Enable the hreflang x-default tag for language:'=>'Omogoči oznako hreflang x-default za jezik:','Enables the hreflang="x-default" for an entire language. See documentation for more details.'=>'Omogoči hreflang="x-default" za celoten jezik. Za več podrobnosti si oglejte dokumentacijo.','Translate numbers and numerals'=>'Prevedi številke in števnike','Enable translation of numbers ( e.g. phone numbers)'=>'Omogoči prevajanje številk ( npr. telefonske številke)','Selector'=>'Selektor','Exclude from dynamic translation'=>'Izključi iz dinamičnega prevajanja','Do not dynamically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated using JavaScript.<br/>These strings will still be translated on the server side if possible.'=>'Ne prevajaj dinamično nizov, ki se nahajajo v HTML vozliščih, ki ustrezajo tem selektorjem.<br>Izključuje vse podrejene elemente HTML vozlišč, ki ustrezajo tem selektorjem, iz prevajanja z uporabo JavaScripta.<br/>Ti nizi bodo še vedno prevedeni na strežniški strani, če je to mogoče.','Gettext String'=>'Gettext niz','Exclude Gettext Strings'=>'Izključi Gettext nize','Exclude these strings from being translated as Gettext strings by TranslatePress. Leave the domain empty to take into account any Gettext string.<br/>Can still be translated through po/mo files.'=>'Izključi te nize iz prevajanja kot Gettext nize s strani TranslatePress. Pustite domeno prazno, da se upošteva kateri koli Gettext niz.<br/>Še vedno jih je mogoče prevesti preko datotek po/mo.','Exclude selectors only from automatic translation'=>'Izključi izbirnike samo iz samodejnega prevoda','Do not automatically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being automatically translated.<br>Manual translation of these strings is still possible.'=>'Ne prevajaj samodejno nizov, ki se nahajajo v HTML vozliščih, ki ustrezajo tem selektorjem.<br>Izključuje vse podrejene elemente HTML vozlišč, ki ustrezajo tem selektorjem, iz samodejnega prevajanja.<br>Ročno prevajanje teh nizov je še vedno mogoče.','Exclude selectors from translation'=>'Izključi izbirnike iz prevoda','Do not translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated.<br>These strings cannot be translated manually nor automatically.'=>'Ne prevajaj nizov, ki se nahajajo v HTML vozliščih, ki ustrezajo tem selektorjem.<br>Izključuje vse podrejene elemente HTML vozlišč, ki ustrezajo tem selektorjem, iz prevajanja.<br>Tih nizov ni mogoče prevesti ročno niti samodejno.','String'=>'Niz','Exclude strings from automatic translation'=>'Izključi nize iz samodejnega prevajanja','Do not automatically translate these strings (ex. names, technical words...)<br>Paragraphs containing these strings will still be translated except for the specified part.'=>'Ne prevajaj samodejno teh nizov (npr. imena, tehnične besede...)<br>Odstavki, ki vsebujejo te nize, bodo še vedno prevedeni, razen določenega dela.','Fix broken HTML'=>'Popravi pokvarjen HTML','General attempt to fix broken or missing HTML on translated pages.<br/>'=>'Splošen poskus popravila pokvarjenega ali manjkajočega HTML na prevedenih straneh.<br/>','Force slash at end of home url:'=>'Vsili poševnico na koncu domačega URL-ja:','Ads a slash at the end of the home_url() function'=>'Doda poševnico na konec funkcije home_url()','Show Both (recommended)'=>'Prikaži oba (priporočeno)','Remove Country Locale'=>'Odstrani državno lokalizacijo','Remove Region Independent Locale'=>'Odstrani splošno lokalizacijo','Remove duplicate hreflang'=>'Odstrani podvojene hreflang','Choose which hreflang tags will appear on your website.<br/>We recommend showing both types of hreflang tags as indicated by <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google Crawling" target="_blank">Google documentation</a>.<br/>Removing Country Locale when having multiple Country Locales of the same language (ex. English UK and English US) will result in showing one hreflang tag with link to just one of the region locales for that language.'=>'Izberite, katere oznake hreflang se bodo prikazovale na vašem spletnem mestu.<br/>Priporočamo prikaz obeh vrst oznak hreflang, kot to navaja <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google Crawling" target="_blank">dokumentacija Google</a>.<br/>Odstranitev državne lokalizacije pri več državnih lokalizacijah istega jezika (npr. angleščina VB in angleščina ZDA) bo povzročila prikaz ene oznake hreflang s povezavo do le ene od regionalnih lokalizacij za ta jezik.','Default (example: en-US, fr-CA, etc.)'=>'Privzeto (primer: en-US, fr-CA, itd.)','Regional (example: en, fr, es, etc.)'=>'Regionalno (primer: en, fr, es, itd.)','HTML Lang Attribute Format'=>'Format atributa lang HTML','Change lang attribute of the html tag to a format that includes country regional or not. <br>In HTML, the lang attribute (<html lang="en-US">)  should be used to  specify the language of text content so that the  browser can correctly display or process  your content (eg. for  hyphenation, styling, spell checking, etc).'=>'Spremenite atribut lang oznake HTML v obliko, ki vključuje kodo države/regije ali ne. <br>V HTML naj bi se atribut lang (<html lang="en-US">)  uporabljal za  določitev jezika besedilne vsebine, tako da  lahko brskalnik pravilno prikaže ali obdela  vašo vsebino (npr. za  deljenje besed s pomišljajem, oblikovanje, preverjanje črkovanja, itd.).','Load legacy Language Switcher'=>'Naloži starejši izbirnik jezika','Applies to all types of language switchers (floating, shortcode, and menu). When enabled, the site will revert to using the original Language Switcher configured in the General Settings tab, replacing the new customizable version. Your existing switcher settings will remain saved, but they will be ignored while this option is active.'=>'Velja za vse vrste izbirnikov jezika (plavajoči, shortcode in meni). Ko je omogočeno, se bo spletno mesto vrnilo k uporabi izvirnega izbirnika jezika, konfiguriranega na zavihku Splošne nastavitve, in nadomestilo novo prilagodljivo različico. Vaše obstoječe nastavitve izbirnika bodo ostale shranjene, vendar bodo prezrte, dokler je ta možnost aktivna.','Load legacy SEO Pack Add-On'=>'Naloži starejši dodatek SEO Pack','In case the recent migration to the new slug rewrite is causing trouble, set this to Yes to use the old method <br> Please <a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">open a support ticket</a> letting us know of the issues you are having.'=>'V primeru, da nedavna migracija na novo prepisovanje slug povzroča težave, nastavite to na Da, da uporabite staro metodo <br> Prosimo, <a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">odprite zahtevek za podporo</a> in nam sporočite težave, ki jih imate.','Manual Translation Only'=>'Samo ročno prevajanje','TranslatePress pro-actively scans and saves strings in the database when users access translated pages. <br>This setting disables this functionality and only allows translation and string saving when inside the Translation Editor. <br>Also disables machine translation outside the Translation Editor, giving you better control over character spending, by translating only the pages you visit in the Translation Editor.'=>'TranslatePress proaktivno pregleduje in shranjuje nize v podatkovno bazo, ko uporabniki dostopajo do prevedenih strani. <br>Ta nastavitev onemogoči to funkcionalnost in dovoli prevajanje ter shranjevanje nizov samo znotraj Urejevalnika prevodov. <br>Onemogoči tudi strojno prevajanje zunaj Urejevalnika prevodov, kar vam omogoča boljši nadzor nad porabo znakov, saj se prevajajo samo strani, ki jih obiščete v Urejevalniku prevodov.','Open language switcher only on click'=>'Odpiraj izbirnik jezika le ob kliku','Open the language switcher shortcode by clicking on it instead of hovering.<br> Close it by clicking on it, anywhere else on the screen or by pressing the escape key. This will affect only the shortcode language switcher.'=>'Odpiraj izbirnik jezika shortcode s klikom nanj namesto z lebdenjem.<br> Zapri ga s klikom nanj, kamorkoli drugam na zaslonu ali s pritiskom na tipko Escape. To bo vplivalo le na izbirnik jezika shortcode.','Show opposite language in the language switcher'=>'Prikaži nasprotni jezik v izbirniku jezika','Transforms the language switcher into a button showing the other available language, not the current one.<br> Only works when there are exactly two languages, the default one and a translation one.<br>This will affect the shortcode language switcher and floating language switcher as well.<br> To achieve this in menu language switcher go to Appearance->Menus->Language Switcher and select Opposite Language.'=>'Pretvori izbirnik jezika v gumb, ki prikaže drugi razpoložljivi jezik, ne trenutnega.<br> Deluje le, ko sta natančno dva jezika, privzeti jezik in jezik prevoda.<br>To bo vplivalo tudi na izbirnik jezika shortcode in plavajoči izbirnik jezika.<br> Da to dosežete v izbirniku jezika v meniju, pojdite na Videz->Meni->Izbirnik jezika in izberite Nasprotni jezik.','TranslatePress gettext database optimization failed.'=>'Optimizacija podatkovne baze gettext za TranslatePress ni uspela.','Retry'=>'Poskusi znova','TranslatePress needs to optimize its gettext database tables. Back up the database, then <a href="%s">start the optimization</a>.'=>'TranslatePress mora optimizirati tabele podatkovne baze gettext. Najprej ustvarite varnostno kopijo podatkovne baze, nato pa <a href="%s">začnite optimizacijo</a>.','Pending gettext database optimization'=>'Optimizacija podatkovne baze gettext v teku','Optimize TranslatePress database tables'=>'Optimiziraj tabele podatkovne baze TranslatePress','<a href="%s">Click here</a> to access the database optimization tool.'=>'<a href="%s">Kliknite tukaj</a> za dostop do orodja za optimizacijo podatkovne baze.','It helps remove possible duplicate translations, clear unnecessary data and repair possible metadata issues.'=>'Pomaga odstraniti morebitne podvojene prevode, počistiti nepotrebne podatke in popraviti morebitne težave z metapodatki.','<a href="%s" target="_blank">Here</a> you can observe the last 5 SQL errors relevant to TranslatePress if they exist.'=>'<a href="%s" target="_blank">Tukaj</a> si lahko ogledate zadnjih 5 SQL napak, povezanih s TranslatePress, če obstajajo.','Troubleshooting'=>'Odpravljanje težav','Exclude Gettext strings'=>'Izključi Gettext nize','Debug'=>'Razhroščevanje','Custom languages'=>'Jeziki po meri','Miscellaneous options'=>'Razne možnosti','Language Switcher'=>'Preklopnik jezika','Exclude strings & pages'=>'Izključi nize & strani','Automatic Translation Memory'=>'Samodejni pomnilnik prevodov','Serve same translation for similar text. The strings need to have a percentage of 95% similarity.<br>Helps prevent losing existing translation when correcting typos or making minor adjustments to the original text. <br>If a translation already exists for a very similar original string, it will automatically be used for the current original string.<br>Does not work when making changes to a text that is part of a translation block unless the new text is manually merged again in a translation block.<br>Each string needs to have a minimum of 50 characters.'=>'Uporabi enak prevod za podobno besedilo. Nizi morajo imeti 95 % podobnosti.<br>Pomaga preprečiti izgubo obstoječega prevoda pri popravljanju tipkarskih napak ali manjših prilagoditvah izvirnega besedila. <br>Če že obstaja prevod za zelo podoben izvirni niz, bo samodejno uporabljen za trenutni izvirni niz.<br>Ne deluje pri spreminjanju besedila, ki je del prevajalskega bloka, razen če je novo besedilo ročno združeno nazaj v prevajalski blok.<br>Vsak niz mora imeti najmanj 50 znakov.','WARNING: This feature can negatively impact page loading times in secondary languages, particularly with large databases (for example websites with a lot of pages or products). If you experience slow loading times, disable this and try again.'=>'OPOZORILO: Ta funkcija lahko negativno vpliva na čase nalaganja strani v sekundarnih jezikih, zlasti pri velikih bazah podatkov (na primer spletna mesta z veliko stranmi ali izdelki). Če opazite počasno nalaganje, to onemogočite in poskusite znova.','Fix missing dynamic content'=>'Popravi manjkajočo dinamično vsebino','May help fix missing content inserted using JavaScript. <br> It shows dynamically inserted content in original language for a moment before the translation request is finished.'=>'Lahko pomaga popraviti manjkajočo vsebino, vstavljeno z JavaScriptom. <br> Za trenutek prikaže dinamično vstavljeno vsebino v izvirnem jeziku, preden je zahtevek za prevod zaključen.','Filter Gettext wrapping from post content and title'=>'Filtriraj Gettext ovoj iz vsebine in naslova prispevka','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post content and post title. Does not affect previous post content. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Filtrira Gettext ovoj, kot je #!trpst#trp-gettext, iz vsebine in naslova posodobljenih prispevkov. Ne vpliva na prejšnjo vsebino prispevka. <br/><strong>Priporočamo varnostno kopijo podatkovne baze, preden to omogočite.</strong>','Filter Gettext wrapping from post meta'=>'Filtriraj Gettext ovoj iz meta podatkov prispevka','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post meta. Does not affect previous post meta. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Filtrira Gettext ovoj, kot je #!trpst#trp-gettext, iz posodobljenih meta podatkov prispevka. Ne vpliva na prejšnje meta podatke prispevka. <br/><strong>Priporočamo varnostno kopijo podatkovne baze, preden to omogočite.</strong>','TranslatePress'=>'TranslatePress','Abilities for managing TranslatePress configuration.'=>'Zmožnosti upravljanja konfiguracije TranslatePress.','Add a translation language'=>'Dodaj prevodni jezik','Adds a translation language to TranslatePress. Enforces the same per-license limit as the settings UI.'=>'Doda prevodni jezik v TranslatePress. Uveljavlja enako omejitev na licenco kot uporabniški vmesnik nastavitev.','WordPress locale code (e.g. fr_FR, de_DE).'=>'Koda locale WordPress (npr. fr_FR, de_DE).','Optional URL slug. Defaults to the ISO language code if omitted.'=>'Izbiren URL slug. Če je izpuščen, je privzeta vrednost ISO jezikovna koda.','Set TranslatePress license key'=>'Nastavi licenčni ključ TranslatePress','Saves a TranslatePress license key and triggers a remote license check, mirroring the onboarding flow.'=>'Shrani licenčni ključ TranslatePress ter sproži oddaljeno preverjanje licence, ki odraža postopek uvajanja.','The license key to activate.'=>'Licenčni ključ za aktivacijo.','Enable Automatic Translation'=>'Omogočite samodejno prevajanje','Turns on Automatic Translation. A valid TranslatePress license is required only when the resolved engine is TranslatePress AI (mtapi); Google Translate and DeepL do not require one. If no engine is passed and none is configured, defaults to mtapi.'=>'Vklaplja samodejni prevod. Veljavna licenca TranslatePress je potrebna le, če je izbrani pogon TranslatePress AI (mtapi); Google Translate in DeepL ne zahtevata licence. Če pogon ni podan in ni nastavljen, je privzeto mtapi.','Optional translation-engine slug to select (e.g. "mtapi", "google_translate_v2", "deepl"). When omitted, keeps the already-configured engine, or defaults to "mtapi" if none is configured.'=>'Izbirni slug pogona za prevajanje (npr. "mtapi", "google_translate_v2", "deepl"). Če je izpuščen, ohrani že nastavljeni pogon ali privzeto nastavi "mtapi", če ni nobenega nastavljenega.','List configured languages'=>'Seznam nastavljenih jezikov','Returns the languages currently configured in TranslatePress, including the default language and per-language slug/publish state.'=>'Vrne trenutno nastavljene jezike v TranslatePress, vključno z privzetim jezikom ter slugom in stanjem objave za posamezen jezik.','List available language codes'=>'Seznam razpoložljivih jezikovnih kod','Returns the full catalog of language codes TranslatePress recognizes, with their English names.'=>'Vrne celoten seznam jezikovnih kod, ki jih prepozna TranslatePress, z njihovimi angleškimi imeni.','Remove a translation language'=>'Odstrani jezik prevoda','Removes a configured translation language. The default language cannot be removed without first reassigning the default.'=>'Odstrani nastavljeni jezik prevoda. Privzetega jezika ni mogoče odstraniti, če najprej ne nastavite drugega privzetega jezika.','Locale code of the language to remove.'=>'Locale koda jezika, ki ga želite odstraniti.','Update a translation language'=>'Posodobi jezik prevoda','Replaces the slug and publish status of an already-configured translation language.'=>'Zamenja slug in stanje objave že nastavljenega jezika prevoda.','Locale code of the language to update.'=>'Locale koda jezika, ki ga želite posodobiti.','URL slug for this language.'=>'URL slug za ta jezik.','Whether this language is published on the front end.'=>'Ali je ta jezik objavljen na frontendu.','Set the default language'=>'Nastavi privzeti jezik','Promotes an already-configured language to be the site default. The previous default remains in the translation languages list.'=>'Nastavi že konfiguriran jezik kot privzeti jezik spletišča. Prejšnji privzeti jezik ostane na seznamu jezikov prevoda.','Locale code to promote to default. Must already be a configured translation language.'=>'Locale koda jezika, ki ga želite nastaviti za privzetega. Jezik mora biti že nastavljen kot jezik prevoda.','You do not have permission to manage TranslatePress settings.'=>'Nimate dovoljenja za upravljanje nastavitev TranslatePress.','Invalid language code. Allowed characters: A-Z, a-z, 0-9, hyphen, underscore.'=>'Neveljavna jezikovna koda. Dovoljeni znaki: A-Z, a-z, 0-9, pomišljaj, podčrtaj.','Language code "%s" is not recognized by TranslatePress.'=>'Jezikovna koda "%s" ni prepoznana v TranslatePress.','Language "%s" is already configured.'=>'Jezik "%s" je že nastavljen.','Your current license allows up to %d additional language(s). Upgrade or activate a Pro license to add more.'=>'Vaša trenutna licenca omogoča do %d dodatnih jezikov. Nadgradite ali aktivirajte Pro licenco, da dodate več.','TranslatePress rejected the new language during settings sanitization.'=>'TranslatePress je med čiščenjem nastavitev zavrnil nov jezik.','Enabling Automatic Translation with the TranslatePress AI engine requires an active TranslatePress license. Activate a license first with translatepress/set-license-key, or pass a different engine (e.g. "google_translate_v2", "deepl").'=>'Vklop samodejnega prevajanja s pogonom TranslatePress AI zahteva aktivno licenco TranslatePress. Najprej aktivirajte licenco z translatepress/set-license-key ali uporabite drug pogon (npr. "google_translate_v2", "deepl").','Your license key expired on %s.'=>'Vaš licenčni ključ je potekel %s.','Your license key has expired.'=>'Vaš licenčni ključ je potekel.','Your license key has been disabled.'=>'Vaš licenčni ključ je bil onemogočen.','Your TranslatePress license key is invalid or missing.'=>'Vaš licenčni ključ TranslatePress je neveljaven ali manjka.','Your license key is disabled for this URL. Re-enable it from your TranslatePress account.'=>'Vaš licenčni ključ je onemogočen za ta URL. Ponovno ga omogočite v svojem TranslatePress Account.','License key mismatch. The license you entered does not match the TranslatePress version you have installed.'=>'Neujemanje licenčnega ključa. Vnesena licenca se ne ujema z nameščeno različico TranslatePress.','Your license key has reached its activation limit.'=>'Vaš licenčni ključ je dosegel omejitev aktivacij.','An error occurred while activating the license, please try again.'=>'Med aktivacijo licence je prišlo do napake, poskusite znova.','Language "%s" is not currently configured.'=>'Jezik "%s" trenutno ni nastavljen.','The default language cannot be removed. Set another language as default first.'=>'Privzetega jezika ni mogoče odstraniti. Najprej nastavite drug jezik kot privzetega.','Slug is empty after sanitization. Use only URL-safe characters.'=>'Slug je po čiščenju prazen. Uporabljajte samo znake, ki so varni za URL.','Language "%s" is not currently configured. Add it first with translatepress/add-language.'=>'Jezik "%s" trenutno ni nastavljen. Najprej ga dodajte z translatepress/add-language.','The default language is always published and cannot be unpublished.'=>'Privzeti jezik je vedno objavljen in ga ni mogoče umakniti iz objave.','Slug "%1$s" is already in use by language "%2$s".'=>'Slug "%1$s" je že v uporabi za jezik "%2$s".','TranslatePress rejected the new settings during sanitization.'=>'TranslatePress je zavrnil nove nastavitve med čiščenjem.','Advanced'=>'Napredno','Are you sure you want to remove this item?'=>'Ali ste prepričani, da želite odstraniti ta element?','Remove'=>'Odstrani','Add'=>'Dodaj','Select...'=>'Izberi...','An error occurred, please try again.'=>'Prišlo je do napake, poskusite znova.','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Vaš licenčni ključ je onemogočen za ta URL. Znova ga omogočite na <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Upravljanje strani.','<p><strong>License key mismatch.</strong> The license you entered doesn’t match the TranslatePress version you have installed.</p><p>Please check that you’ve installed the correct version for your license from your TranslatePress account.</p>'=>'<p><strong>Neujemanje licenčnega ključa.</strong> Vnesena licenca se ne ujema z nameščeno različico TranslatePress.</p><p>Preverite, ali ste iz svojega računa TranslatePress namestili pravilno različico za vašo licenco.</p>','If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'Če imate nameščen samo brezplačni vtičnik, vendar ste dodali plačano licenco, namestite plačani vtičnik iz svojega računa TranslatePress.','Upgrade your plan to add more sites. %1$sUpgrade now%2$s'=>'Nadgradite načrt za dodajanje več strani. %1$sNadgradite zdaj%2$s','You have successfully activated your license'=>'Uspešno ste aktivirali svojo licenco.','[%s] Low TranslatePress AI Words'=>'[%s] Zmanjkuje besed TranslatePress AI','upgrade your plan'=>'Nadgradite svoj paket','upgrade your plan or get extra AI Words'=>'Nadgradite svoj paket ali pridobite dodatne AI-besede','TranslatePress AI words are running low on your site.'=>'Na vašem spletišču zmanjkuje besed TranslatePress AI.','Current status: %s words remaining'=>'Trenutni status: preostalo %s besed','Once the remaining AI words run out, automatic translation through TranslatePress AI will be paused.'=>'Ko zmanjka preostalih besed TranslatePress AI, bo samodejni prevod prek TranslatePress AI začasno zaustavljen.','To continue translating your content, please %1$s over at %2$s'=>'Za nadaljevanje prevajanja vsebine %1$s na %2$s','Manage Notification: %s'=>'Upravljanje obvestil: %s','Others'=>'Ostali','Restrict by Language'=>'Omeji po jeziku','Exclude from Language'=>'Izključi iz jezika','Restrict element to language'=>'Omeji element na jezik','Show this element only in one language.'=>'Prikaži ta element samo v enem jeziku.','Enable translation'=>'Omogoči prevajanje','Allow translation to the corresponding language only if the content is written in the default language.'=>'Dovoli prevajanje v ustrezen jezik le, če je vsebina napisana v privzetem jeziku.','Select language'=>'Izberite jezik','Choose in which language to show this element.'=>'Izberite jezik, v katerem naj se prikaže ta element.','Exclude element from language'=>'Izključi element iz jezika','Exclude this element from specific languages.'=>'Izključi ta element iz določenih jezikov.','Select languages'=>'Izberite jezike','Choose from which languages to exclude this element.'=>'Izberite jezike, iz katerih želite izključiti ta element.','This element will still be visible when you are translating your website through the Translation Editor.'=>'Ta element bo še vedno viden med prevajanjem spletnega mesta v urejevalniku prevodov.','The content of this element should be written in the default language.'=>'Vsebina tega elementa mora biti napisana v privzetem jeziku.','<strong>TranslatePress</strong> encountered SQL errors. <a href="%s" title="View TranslatePress SQL Errors">Check out the errors</a>.'=>'<strong>TranslatePress</strong> je naletel na napake SQL. <a href="%s" title="View TranslatePress SQL Errors">Preverite napake</a>.','Automatic translation has been disabled.'=>'Samodejno prevajanje je bilo onemogočeno.','Logged errors'=>'Zabeležene napake','These are the most recent 5 errors logged by TranslatePress:'=>'To je zadnjih 5 napak, ki jih je zabeležil TranslatePress:','Yes'=>'Da','Why are these errors occuring'=>'Zakaj se pojavljajo te napake','If TranslatePress detects something wrong when executing queries on your database, it may disable the Automatic Translation feature in order to avoid any extra charging by Google/DeepL. Automatic Translation needs to be manually turned on, after you solve the issues.'=>'Če TranslatePress pri izvajanju poizvedb v vaši zbirki podatkov zazna kaj narobe, lahko onemogoči funkcijo samodejnega prevajanja, da se izogne dodatnim stroškom pri Googlu/DeepL. Samodejno prevajanje je treba ročno vklopiti, potem ko odpravite težave.','The SQL errors detected can occur for various reasons including missing tables, missing permissions for the SQL user to create tables or perform other operations, problems after site migration or changes to SQL server configuration.'=>'Zaznane napake SQL se lahko pojavijo iz različnih razlogov, vključno z manjkajočimi tabelami, manjkajočimi dovoljenji za uporabnika SQL za ustvarjanje tabel ali izvajanje drugih operacij, težavami po selitvi spletišča ali spremembami konfiguracije strežnika SQL.','What you can do in this situation'=>'Kaj lahko storite v tej situaciji','Plan A.'=>'Načrt A.','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL settings. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Pojdite v Nastavitve -> TranslatePress -> zavihek Splošno in shranite nastavitve. S tem boste regenerirali tabele z uporabo trenutnih nastavitev SQL. Preverite, ali se pri brskanju po vašem spletišču v prevedenem jeziku ne pojavljajo več napake. Poglejte časovne žige napak, da se prepričate, da ne vidite starih napak. Prikazanih je samo najnovejših 5 napak.','Plan B.'=>'Načrt B.','If your problem isn\'t solved, try the following steps:'=>'Če vaša težava ni odpravljena, poskusite naslednje korake:','Create a backup of your database'=>'Ustvarite varnostno kopijo svoje zbirke podatkov','Create a copy of each translation table where you encounter errors. You can copy the table within the same database (trp_dictionary_en_us_es_es_COPY for example) -- perform this step only if you want to keep the current translations'=>'Ustvarite kopijo vsake tabele za prevode, kjer naletite na napake. Tabelo lahko kopirate znotraj iste zbirke podatkov (npr. trp_dictionary_en_us_es_es_COPY) — ta korak izvedite samo, če želite ohraniti trenutne prevode','Remove the trouble tables by executing the DROP function on them'=>'Odstranite težavne tabele z izvedbo funkcije DROP na njih','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL server.'=>'Pojdite v Nastavitve -> TranslatePress -> zavihek Splošno in shranite nastavitve. S tem boste regenerirali tabele z uporabo trenutnega strežnika SQL.','Copy the relevant content from the duplicated tables (trp_dictionary_en_us_es_es_COPY for example) in the newly generated table (trp_dictionary_en_us_es_es) -- perform this step only if you want to keep the current translations'=>'Kopirajte ustrezno vsebino iz podvojenih tabel (npr. trp_dictionary_en_us_es_es_COPY) v novo generirano tabelo (trp_dictionary_en_us_es_es) — ta korak izvedite samo, če želite ohraniti trenutne prevode','Test it to see if everything is working. If something went wrong, you can restore the backup that you\'ve made at the first step. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Preizkusite, če vse deluje. Če je šlo kaj narobe, lahko obnovite varnostno kopijo, ki ste jo ustvarili v prvem koraku. Preverite, ali se pri brskanju po vašem spletišču v prevedenem jeziku ne pojavljajo več napake. Poglejte časovne žige napak, da se prepričate, da ne vidite starih napak. Prikazanih je samo najnovejših 5 napak.','Plan C.'=>'Načrt C.','If your problem still isn\'t solved, try asking your hosting about your errors. The most common issue is missing permissions for the SQL user, such as the Create Tables permission.'=>'Če vaša težava še vedno ni odpravljena, poskusite vprašati vašega gostitelja glede napak. Najpogostejši problem so manjkajoča dovoljenja za uporabnika SQL, kot je dovoljenje za ustvarjanje tabel.','Could not install. Try again from <a href="%s" >Plugins Dashboard.</a>'=>'Ni bilo mogoče namestiti. Poskusite znova v <a href="%s" >Nadzorna plošča vtičnikov.</a>','Settings scope unknown.'=>'Neznan obseg nastavitev.','Legacy disabled.'=>'Zastarel način onemogočen.','Change language to %s'=>'Spremeni jezik v %s','Automatic Translation'=>'Samodejno prevajanje','Unsupported languages'=>'Nepodprti jeziki','The selected automatic translation engine does not provide support for these languages.<br>You can still manually translate pages in these languages using the Translation Editor.'=>'Izbrani pogon za samodejno prevajanje ne podpira teh jezikov.<br>Strani v teh jezikih lahko še vedno ročno prevajate z urejevalnikom prevodov.','General'=>'Splošno','Glossary'=>'Slovar','API key validation failed.'=>'Preverjanje API ključa ni uspelo.','API key verification was successful.'=>'Preverjanje API ključa je bilo uspešno.','Please enter your Google Translate key.'=>'Vnesite svoj Google Translate ključ.','Not TranslatePress onboarding page.'=>'To ni stran za uvod v TranslatePress.','Step %s does not exist'=>'Korak %s ne obstaja','Welcome'=>'Dobrodošli','Add Languages'=>'Dodaj jezike','Enable Addons'=>'Omogoči dodatke','Finalize'=>'Zaključi','Exit Setup'=>'Zapusti nastavitev','Upgrade'=>'Nadgradi','Nothing here'=>'Tukaj ni ničesar','Your <strong>TranslatePress</strong> license is missing or invalid. <br/>Please %1$sregister your copy%2$s to enable automatic website translation via TranslatePress AI, premium addons, automatic updates and support. Need a license key? %3$sPurchase one now%4$s'=>'Vaša licenca za <strong>TranslatePress</strong> manjka ali je neveljavna. <br/>Prosimo, %1$sregistrirajte svojo kopijo%2$s, da omogočite samodejno prevajanje spletnega mesta prek TranslatePress AI, premium dodatke, samodejne posodobitve in podporo. Potrebujete licenčni ključ? %3$sKupite ga zdaj%4$s','Your license is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Vaša licenca je onemogočena za ta URL. Znova jo omogočite na <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Upravljanje spletišč.','You have reached the activation limit for your <strong>%1$s</strong> license. <br/>Manage your active sites from %2$s your account %3$s.'=>'Dosegli ste omejitev aktivacije za vašo licenco <strong>%1$s</strong>. <br/>Upravljajte svoja aktivna spletišča iz %2$s vašega računa %3$s.','License key mismatch. The license you entered doesn’t match the <strong>%1$s</strong> version you have installed. <br/>Please check that you’ve installed the correct version for your license from your %2$sTranslatePress account%3$s.'=>'Neujemanje licenčnega ključa. Vnesena licenca se ne ujema z nameščeno različico <strong>%1$s</strong>. <br/>Preverite, ali ste za vašo licenco iz vašega %2$sTranslatePress Account%3$s namestili pravilno različico.','<br/>If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'<br/>Če imate nameščen samo brezplačni vtičnik, vendar ste dodali plačano licenco, namestite plačani vtičnik iz vašega TranslatePress Account.','Your <strong>TranslatePress</strong> license has expired. <br/>Please %1$sRenew Your Licence%2$s to continue receiving access to automatic translations via TranslatePress AI, premium addons, product downloads, and automatic updates. %3$sRenew now %4$s'=>'Vaša licenca za <strong>TranslatePress</strong> je potekla. <br/>Prosimo, %1$sObnovite svojo licenco%2$s, da boste še naprej imeli dostop do samodejnih prevodov prek TranslatePress AI, premium dodatkov, prenosov izdelkov in samodejnih posodobitev. %3$sObnovi zdaj %4$s','Error: '=>'Napaka: ','Something went wrong, please try again.'=>'Nekaj je šlo narobe, poskusite znova.','Your <strong>TranslatePress</strong> license will expire on %1$s. Please %2$sRenew Your Licence%3$s to continue receiving access to automatic translations via TP AI, premium addons, product downloads and automatic updates. %4$sRenew Now%5$s'=>'Vaša licenca za <strong>TranslatePress</strong> bo potekla %1$s. Prosimo, %2$sObnovite svojo licenco%3$s, da boste še naprej imeli dostop do samodejnih prevodov prek TP AI, premium dodatkov, prenosov izdelkov in samodejnih posodobitev. %4$sObnovi zdaj%5$s','Please %1$senter%2$s your license key to enable %3$s automatic translation.'=>'Prosimo, %1$svnesite%2$s svoj licenčni ključ, da omogočite samodejno prevajanje %3$s.','%1$s automatic translation requires an active license. Please %2$srenew%3$s your license or purchase a new one %4$shere%5$s.'=>'Samodejno prevajanje %1$s zahteva aktivno licenco. Prosimo, %2$sobnovite%3$s svojo licenco ali kupite novo %4$stukaj%5$s.','You have less than 5,000 TranslatePress AI words remaining. To continue automatically translating your website, please %spurchase additional AI words at a discount from your account%s.'=>'Imate manj kot 5000 besed TranslatePress AI. Če želite še naprej samodejno prevajati svoje spletno mesto, %skupite dodatne AI besede s popustom prek svojega računa%s.','You do not have a valid license for <strong>TranslatePress</strong>. %1$sGet one for free%2$s to get access to TranslatePress AI.'=>'Nimate veljavne licence za <strong>TranslatePress</strong>. %1$sPridobite jo brezplačno%2$s, da pridobite dostop do TranslatePress AI.',' Error: '=>' Napaka: ','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Learn more</a>.'=>'<strong>NOVO:</strong> Dodatek <strong>Različna domena za vsak jezik</strong> je tu! Izboljšajte svoj globalni SEO in ustvarite lokalno izkušnjo z domenami za posamezne države, kot so .de ali .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Več informacij</a>.','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. Upgrade to <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business or Developer</a> to access it + more premium perks!'=>'<strong>NOVO:</strong> Dodatek <strong>Različna domena za vsak jezik</strong> je tu! Izboljšajte svoj globalni SEO in ustvarite lokalno izkušnjo z domenami za posamezne države, kot so .de ali .fr. Nadgradite na <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business ali Developer</a>, da dostopate do njega + več premium ugodnosti!','The daily quota for machine translation characters exceeded. Please check the <strong>TranslatePress -> <a href="%s">Automatic Translation</a></strong> page for more information.'=>'Dnevna kvota znakov za strojno prevajanje je presežena. Preverite stran <strong>TranslatePress -> <a href="%s">Samodejno prevajanje</a></strong> za več informacij.','Marketing optin'=>'Marketing prijava','Opt in to our security and feature updates notifications, and non-sensitive diagnostic tracking.'=>'Strinjajte se z obveščanjem o varnostnih in funkcionalnih posodobitvah ter z nesenzitivnim diagnostičnim sledenjem.','TranslatePress Preferred User Language'=>'TranslatePress želeni jezik uporabnika','Preferred language to navigate the site'=>'Želeni jezik za brskanje po spletni strani','The language is automatically set based by the last visited language by the user.'=>'Jezik se samodejno nastavi glede na zadnji obiskani jezik uporabnika.','Always use this language'=>'Vedno uporabi ta jezik','By checking this setting the preferred language will remain the one selected above, without the possibility of being changed in the frontend.<br>This language will be used in different operations such as sending email to the user.'=>'Če označite to nastavitev, bo želeni jezik ostal takšen, kot je izbran zgoraj, brez možnosti spreminjanja na sprednjem delu spletišča.<br>Ta jezik bo uporabljen pri različnih operacijah, kot je pošiljanje e-pošte uporabniku.','Hello! Seems like you\'ve been using <strong>TranslatePress</strong> for a while now to translate your website. That\'s awesome! '=>'Pozdravljeni! Kaže, da že nekaj časa uporabljate <strong>TranslatePress</strong> za prevajanje svoje spletne strani. Odlično! ','If you can spare a few moments to rate it on WordPress.org it would help us a lot (and boost my motivation).'=>'Če si lahko vzamete nekaj trenutkov za ocenitev na WordPress.org, nam bo to veliko v pomoč (in povečalo mojo motivacijo).','~ Razvan, developer of TranslatePress'=>'~ Razvan, razvijalec TranslatePress','Rate TranslatePress on WordPress.org plugin page'=>'Ocenite TranslatePress na strani vtičnika WordPress.org','Ok, I will gladly help!'=>'V redu, z veseljem pomagam!','No, thanks.'=>'Ne, hvala.','Full Language Names'=>'Polna imena jezikov','Short Language Names'=>'Kratka imena jezikov','Flags with Full Language Names'=>'Zastavice s polnimi imeni jezikov','Flags with Short Language Names'=>'Zastavice s kratkimi imeni jezikov','Only Flags'=>'Samo zastavice','Full Language Names No HTML'=>'Polna imena jezikov brez HTML','Bottom Right'=>'Spodaj desno','Bottom Left'=>'Spodaj levo','Top Right'=>'Zgoraj desno','Top Left'=>'Zgoraj levo','Dark'=>'Temno','Light'=>'Svetlo','Install & Activate'=>'Namesti in aktiviraj','Invalid language code. Please try again.'=>'Neveljavna koda jezika. Poskusite znova.','Language codes can contain only A-Z a-z 0-9 - _ characters. Check your language codes in TranslatePress General Settings.'=>'Kode jezikov lahko vsebujejo le znake A-Z a-z 0-9 - _. Preverite kode jezikov v splošnih nastavitvah TranslatePress.','Error! Duplicate URL slug values.'=>'Napaka! Podvojene vrednosti URL slug-a.','You cannot select two languages that have the same <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">iso code</a> but different formalities because doing so will lead to duplicate <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">hreflang tags</a>.'=>'Ne morete izbrati dveh jezikov, ki imata enako <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">iso kodo</a>, vendar različne formalnosti, ker bo to povzročilo podvojene <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">hreflang oznake</a>.','Duplicate language detected.<br>Each language can only be added once to ensure accurate translation management.<br> Please change the duplicate language entry and try again. '=>'Zaznan podvojen jezik.<br>Vsak jezik lahko dodate samo enkrat za natančno upravljanje prevodov.<br> Spremenite podvojeni vnos jezika in poskusite znova. ','Current Language'=>'Trenutni jezik','Opposite Language'=>'Nasprotni jezik','Addons'=>'Dodatki','Settings'=>'Nastavitve','Pro Features'=>'Pro funkcije','Activate License'=>'Aktiviraj licenco','Need Help?'=>'Potrebujete pomoč?','Recent community discussions'=>'Nedavne razprave v skupnosti','Loading...'=>'Nalaganje...','Unable to load forum posts'=>'Ni mogoče naložiti objav foruma.','Ask a Question'=>'Zastavite vprašanje','View All Topics'=>'Ogled vseh tem','by'=>'od','Have a question?'=>'Imate vprašanje?','Get help directly from the plugin developers, suggest improvements, or share your feedback!'=>'Poiščite pomoč neposredno pri razvijalcih vtičnika, predlagajte izboljšave ali delite povratne informacije!','Tip for faster help:'=>'Nasvet za hitrejšo pomoč:','Include what you tried, what you expected, and what happened. Screenshots help!'=>'Vključite, kaj ste poskusili, kaj ste pričakovali in kaj se je zgodilo. Posnetki zaslona pomagajo!','Toggle support chat'=>'Preklopi klepet za podporo','Ask the community'=>'Vprašajte skupnost','Close'=>'Zapri','Empty feed response'=>'Prazen odziv vira','Unable to parse feed'=>'Ni mogoče razčleniti vira','Just now'=>'Pravkar','%d hour ago'=>'pred %d uro' . "\0" . 'pred %d urama' . "\0" . 'pred %d urami' . "\0" . 'pred %d urami','%d day ago'=>'pred %d dnem' . "\0" . 'pred %d dnevoma' . "\0" . 'pred %d dnevi' . "\0" . 'pred %d dnevi','Source'=>'Vir','Srcset'=>'Srcset','Alt attribute'=>'Atribut alt','Title attribute'=>'Atribut title','Anchor link'=>'Sidrna povezava','Placeholder attribute'=>'Atribut placeholder','Submit attribute'=>'Atribut submit','Text'=>'Besedilo','Video Poster'=>'Poster videa','plural form'=>'Množinska oblika','one'=>'Ena','few'=>'Nekaj','many'=>'Veliko','other'=>'Druga','Saved'=>'Shranjeno','Save'=>'Shrani','Saving translation...'=>'Shranjevanje prevoda...','You have unsaved changes!'=>'Imate neshranjene spremembe!','Discard changes'=>'Zavrzi spremembe','Discard All'=>'Zavrzi vse','Loading Strings...'=>'Nalaganje nizov...','Select string to translate...'=>'Izberite niz za prevajanje...','Close Editor'=>'Zapri urejevalnik','From'=>'Iz','To'=>'V','Add Media'=>'Dodaj medij','Other languages'=>'Drugi jeziki','Context'=>'Kontekst','View Website As'=>'Ogled spletnega mesta kot','Available in our Pro Versions'=>'Na voljo v naših Pro različicah','Select or Upload Media'=>'Izberi ali naloži medij','Use this media'=>'Uporabi ta medij','Translate'=>'Prevedi','Translate entire block element'=>'Prevedi celoten element bloka','Split block to translate strings individually'=>'Razdeli blok za prevajanje posameznih nizov','Save changes to translation. Shortcut: CTRL(⌘) + S'=>'Shrani spremembe prevoda. Bližnjica: CTRL(⌘) + S','Navigate to next string in dropdown list. Shortcut: CTRL(⌘) + ALT + Right Arrow'=>'Pomaknite se na naslednji niz v spustnem seznamu. Bližnjica: CTRL(⌘) + ALT + desna puščica','Navigate to previous string in dropdown list. Shortcut: CTRL(⌘) + ALT + Left Arrow'=>'Pomaknite se na prejšnji niz v spustnem seznamu. Bližnjica: CTRL(⌘) + ALT + leva puščica','Discard all changes. Shortcut: CTRL(⌘) + ALT + Z'=>'Zavrzi vse spremembe. Bližnjica: CTRL(⌘) + ALT + Z','Discard changes to this text box. To discard changes to all text boxes use shortcut: CTRL(⌘) + ALT + Z'=>'Zavrzi spremembe v tem besedilnem polju. Če želiš zavreči spremembe v vseh besedilnih poljih, uporabi bližnjico: CTRL(⌘) + ALT + Z','Dismiss tooltip'=>'Skrij namig','Quick Intro'=>'Kratek uvod','Are you sure you want to split this phrase into smaller parts?'=>'Ali ste prepričani, da želite razdeliti ta izraz na manjše dele?','This string is not ready for translation yet. <br>Try again in a moment...'=>'Ta niz še ni pripravljen za prevod.<br>Poskusite znova čez trenutek...','For this option to work, please update the Browse as other role add-on to the latest version.'=>'Da bo ta možnost delovala, posodobite razširitev Browse as other role na najnovejšo različico.','To translate slugs, please update the SEO Pack add-on to the latest version.'=>'Za prevajanje slug-ov posodobite dodatek SEO Pack na najnovejšo različico.','You can add a new language from <a href="%s">Settings->TranslatePress</a>'=>'Nov jezik lahko dodate v <a href="%s">Nastavitve->TranslatePress</a>','However, you can still use TranslatePress to <strong style="background: #f5fb9d;">modify gettext strings</strong> available in your page.'=>'Vendar lahko še vedno uporabite TranslatePress za <strong style="background: #f5fb9d;">spreminjanje nizov Gettext</strong>, ki so na voljo na vaši strani.','Strings that are user-created cannot be modified, only those from themes and plugins.'=>'Nizi, ki jih je ustvaril uporabnik, se ne morejo spreminjati, le tisti iz tem in vtičnikov.','Extra Translation Features'=>'Dodatne funkcije prevajanja','Support for 130+ Extra Languages'=>'Podpora za 130+ dodatnih jezikov','Access to TranslatePress AI'=>'Dostop do TranslatePress AI','Translate SEO Title, Description, Slug'=>'Prevedi SEO naslov, opis in slug','Publi